using System;using System.IO;using UnityEngine;using UnityEditor;using Newtonsoft.Json;
public static class B3LiveFrame {public static object Run(){if(!Application.isPlaying||Time.frameCount<10)throw new Exception("Advancing Play required");var c=Camera.main;if(!c)throw new Exception("No game camera");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var rt=new RenderTexture(1440,1000,24){antiAliasing=4};var previous=RenderTexture.active;var target=c.targetTexture;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,1000),0,0);tex.Apply();File.WriteAllBytes(r+"/Docs/Review/2026-11-09_B3_FullFloor/play_game_camera.png",tex.EncodeToPNG());}finally{RenderTexture.active=previous;c.targetTexture=target;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}var result=new{frame=Time.frameCount,time=Time.time,camera=c.name,position=c.transform.position.ToString(),c.enabled,c.useOcclusionCulling};File.WriteAllText(r+"/Docs/Review/2026-11-09_B3_FullFloor/play_game_camera.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}}
